import{_ as i,a0 as t,w as o,s as r,ao as d,I as l,a1 as e,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"在 Linux 上用 DNS 實現簡單的負載均衡 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 DNS 實現簡單的負載均衡 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 DNS 實現簡單的負載均衡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 DNS 實現簡單的負載均衡 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180322 Simple Load Balancing with DNS on Linux","title":"在 Linux 上用 DNS 實現簡單的負載均衡","tag":"201806","desc":""},"relativePath":"201806/20180322 Simple Load Balancing with DNS on Linux.md","filePath":"[post].md"}'),m={name:"201806/20180322 Simple Load Balancing with DNS on Linux.md"};function c(u,s,f,h,b,x){const n=t("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="在-linux-上用-dns-實現簡單的負載均衡" tabindex="-1">在 Linux 上用 DNS 實現簡單的負載均衡 <a class="header-anchor" href="#在-linux-上用-dns-實現簡單的負載均衡" aria-label="Permalink to “在 Linux 上用 DNS 實現簡單的負載均衡”">​</a></h1><blockquote><p>DNS 輪詢將多個服務器映射到同一個主機名，並沒有為這裏展示的魔法做更多的工作。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/american-robin-920.jpg?itok=_B_RRbfj" alt=""></p><p>如果你的後端服務器是由多台服務器構成的，比如集羣化或者鏡像的 Web 或者文件服務器，通過負載均衡器提供了單一的入口點。業務繁忙的大型電商在高端負載均衡器上花費了大量的資金，用它來執行各種各樣的任務：代理、緩存、狀況檢查、SSL 處理、可配置的優先級、流量整形等很多任務。</p><p>但是你並不需要做那麼多工作的負載均衡器。你需要的是一個跨服務器分發負載的簡單方法，它能夠提供故障切換，並且不太在意它是否高效和完美。DNS 輪詢和使用輪詢的子域委派是實現這個目標的兩種簡單方法。</p><p>DNS 輪詢是將多台服務器映射到同一個主機名上，當用户訪問 <code>foo.example.com</code> 時多台服務器都可用於處理它們的請求，使用的就是這種方式。</p><p>當你有多個子域或者你的服務器在地理上比較分散時，使用輪詢的子域委派就比較有用。你有一個主域名服務器，而子域有它們自己的域名服務器。你的主域名服務器將所有的到子域的請求指向到它們自己的域名服務器上。這將提升響應時間，因為 DNS 協議會自動查找最快的鏈路。</p><h3 id="dns-輪詢" tabindex="-1">DNS 輪詢 <a class="header-anchor" href="#dns-輪詢" aria-label="Permalink to “DNS 輪詢”">​</a></h3><p>輪詢和<ruby>旅鶇鳥<rt>robins</rt></ruby>沒有任何關係，據我相熟的圖書管理員説，它最初是一個法語短語，<em>ruban rond</em>、或者 <em>round ribbon</em>。很久以前，法國政府官員以不分級的圓形、波浪線、或者直線形狀來在請願書上簽字，以蓋住原來的發起人。</p><p>DNS 輪詢也是不分級的，簡單配置一個服務器列表，然後將請求轉到每個服務器上。它並不做真正的負載均衡，因為它根本就不測量負載，也沒有狀況檢查，因此如果一個服務器宕機，請求仍然會發送到那個宕機的服務器上。它的優點就是簡單。如果你有一個小的文件或者 Web 服務器集羣，想通過一個簡單的方法在它們之間分散負載，那麼 DNS 輪詢很適合你。</p><p>你所做的全部配置就是創建多條 A 或者 AAAA 記錄，映射多台服務器到單個的主機名。這個 BIND 示例同時使用了 IPv4 和 IPv6 私有地址類：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fileserv.example.com. IN A 172.16.10.10</span></span>
<span class="line"><span>fileserv.example.com. IN A 172.16.10.11</span></span>
<span class="line"><span>fileserv.example.com. IN A 172.16.10.12</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::10</span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::11</span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::12</span></span></code></pre></div><p>Dnsmasq 在 <code>/etc/hosts</code> 文件中保存 A 和 AAAA 記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>172.16.1.10 fileserv fileserv.example.com</span></span>
<span class="line"><span>172.16.1.11 fileserv fileserv.example.com</span></span>
<span class="line"><span>172.16.1.12 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::10 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::11 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::12 fileserv fileserv.example.com</span></span></code></pre></div><p>請注意這些示例都是很簡化的，解析完全合格域名有多種方法，因此，關於如何配置 DNS 請自行學習。</p><p>使用 <code>dig</code> 命令去檢查你的配置能否按預期工作。將 <code>ns.example.com</code> 替換為你的域名服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig @ns.example.com fileserv A fileserv AAA</span></span></code></pre></div><p>它將同時顯示出 IPv4 和 IPv6 的輪詢記錄。</p><h3 id="子域委派和輪詢" tabindex="-1">子域委派和輪詢 <a class="header-anchor" href="#子域委派和輪詢" aria-label="Permalink to “子域委派和輪詢”">​</a></h3><p>子域委派結合輪詢要做的配置會更多，但是這樣有一些好處。當你有多個子域或者地理位置比較分散的服務器時，就應該去使用它。它的響應時間更快，並且宕機的服務器不會去響應，因此客户端不會因為等待回覆而被掛住。一個短的 TTL，比如 60 秒，就能幫你做到。</p><p>這種方法需要多台域名服務器。在最簡化的場景中，你需要一台主域名服務器和兩個子域，每個子域都有它們自己的域名服務器。在子域服務器上配置你的輪詢記錄，然後在你的主域名服務器上配置委派。</p><p>在主域名服務器上的 BIND 中，你至少需要兩個額外的配置，一個區聲明以及在區數據文件中的 A/AAAA 記錄。主域名服務器中的委派應該像如下的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ns1.sub.example.com. IN A 172.16.1.20</span></span>
<span class="line"><span>ns1.sub.example.com. IN AAAA fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>ns2.sub.example.com. IN A 172.16.1.21</span></span>
<span class="line"><span>ns2.sub.example.com. IN AAA fd02:faea:f561:8fa0:1::21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN NS ns2.sub.example.com.</span></span></code></pre></div><p>接下來的每台子域服務器上有它們自己的區文件。在這裏它的關鍵點是每個服務器去返回它<strong>自己的</strong> IP 地址。在 <code>named.conf</code> 中的區聲明，所有的服務上都是一樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;sub.example.com&quot; {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;db.sub.example.com&quot;;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>然後數據文件也是相同的，除了那個 A/AAAA 記錄使用的是各個服務器自己的 IP 地址。SOA 記錄都指向到主域名服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; first subdomain name server</span></span>
<span class="line"><span>$ORIGIN sub.example.com.</span></span>
<span class="line"><span>$TTL 60</span></span>
<span class="line"><span>sub.example.com  IN SOA ns1.example.com. admin.example.com. (</span></span>
<span class="line"><span>        2018123456      ; serial</span></span>
<span class="line"><span>        3H              ; refresh</span></span>
<span class="line"><span>        15              ; retry</span></span>
<span class="line"><span>        3600000         ; expire</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN A  172.16.1.20</span></span>
<span class="line"><span>ns1.sub.example.com.  IN AAAA  fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>; second subdomain name server</span></span>
<span class="line"><span>$ORIGIN sub.example.com.</span></span>
<span class="line"><span>$TTL 60</span></span>
<span class="line"><span>sub.example.com  IN SOA ns1.example.com. admin.example.com. (</span></span>
<span class="line"><span>        2018234567      ; serial</span></span>
<span class="line"><span>        3H              ; refresh</span></span>
<span class="line"><span>        15              ; retry</span></span>
<span class="line"><span>        3600000         ; expire</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN A  172.16.1.21</span></span>
<span class="line"><span>ns2.sub.example.com.  IN AAAA  fd02:faea:f561:8fa0:1::21</span></span></code></pre></div><p>接下來生成子域服務器上的輪詢記錄，方法和前面一樣。現在你已經有了多個域名服務器來處理到你的子域的請求。再説一次，BIND 是很複雜的，做同一件事情它有多種方法，因此，給你留的家庭作業是找出適合你使用的最佳配置方法。</p><p>在 Dnsmasq 中做子域委派很容易。在你的主域名服務器上的 <code>dnsmasq.conf</code> 文件中添加如下的行，去指向到子域的域名服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server=/sub.example.com/172.16.1.20</span></span>
<span class="line"><span>server=/sub.example.com/172.16.1.21</span></span>
<span class="line"><span>server=/sub.example.com/fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>server=/sub.example.com/fd02:faea:f561:8fa0:1::21</span></span></code></pre></div><p>然後在子域的域名服務器上的 <code>/etc/hosts</code> 中配置輪詢。</p><p>獲取配置方法的詳細內容和幫助，請參考這些資源：</p>`,32)),l("ul",null,[l("li",null,[e(n,{href:"http://www.thekelleys.org.uk/dnsmasq/doc.html"},{default:p(()=>[...s[0]||(s[0]=[a("Dnsmasq",-1)])]),_:1})]),l("li",null,[e(n,{href:"http://shop.oreilly.com/product/9780596100575.do"},{default:p(()=>[...s[1]||(s[1]=[a("DNS and BIND, 5th Edition",-1)])]),_:1})])]),l("p",null,[s[3]||(s[3]=a("通過來自 Linux 基金會和 edX 的免費課程 ",-1)),e(n,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:p(()=>[...s[2]||(s[2]=[a('"Linux 入門" ',-1)])]),_:1}),s[4]||(s[4]=a(" 學習更多 Linux 的知識。",-1))]),s[19]||(s[19]=l("hr",null,null,-1)),l("p",null,[s[6]||(s[6]=a("via: ",-1)),e(n,{href:"https://www.linux.com/learn/intro-to-linux/2018/3/simple-load-balancing-dns-linux"},{default:p(()=>[...s[5]||(s[5]=[a("https://www.linux.com/learn/intro-to-linux/2018/3/simple-load-balancing-dns-linux",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.linux.com/users/cschroder"},{default:p(()=>[...s[7]||(s[7]=[a("CARLA SCHRODER",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/qhwdw"},{default:p(()=>[...s[8]||(s[8]=[a("qhwdw",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const N=i(m,[["render",c]]);export{A as __pageData,N as default};
